package solution

import "testing"

func TestCardServiceUpdateAndSnapshots(t *testing.T) {
	cards := []Card{
		{ID: 1, Board: "alpha", Name: "old", Slug: "old-slug", Title: "Old title"},
		{ID: 1, Board: "alpha", Name: "replacement", Slug: "r", Title: "R"},
		{ID: 2, Board: "beta", Name: "two", Slug: "two", Title: "Two"},
	}
	access := map[string][]string{"alice": {"alpha"}}
	s := NewCardService(cards, access, true, true)
	cards[1].Name = "mutated"
	access["alice"][0] = "beta"
	access["alice"] = append(access["alice"], "beta")

	updated, err := s.UpdateCard("alice", "alpha", 1, []byte(`{"name":"new","title":"New title"}`))
	if err != nil {
		t.Fatal(err)
	}
	want := Card{ID: 1, Board: "alpha", Name: "new", Slug: "r", Title: "New title"}
	if updated != want {
		t.Fatalf("updated = %#v, want %#v", updated, want)
	}
	search := s.SearchCopy()
	if search == nil || search[1] != want {
		t.Fatalf("search snapshot = %#v", search)
	}
	events := s.EventsCopy()
	if len(events) != 1 || events[0] != want {
		t.Fatalf("events snapshot = %#v", events)
	}
	search[1] = Card{Name: "corrupt"}
	events[0].Name = "corrupt"
	if s.SearchCopy()[1] != want || s.EventsCopy()[0] != want {
		t.Fatal("snapshot mutation altered service state")
	}
	if _, err := s.UpdateCard("alice", "beta", 2, []byte(`{"name":"x"}`)); err != ErrUnauthorized {
		t.Fatalf("constructor did not copy access, error = %v", err)
	}
}

func TestCardServiceErrorsAreAtomic(t *testing.T) {
	original := Card{ID: 7, Board: "b", Name: "n", Slug: "s", Title: "t"}
	s := NewCardService([]Card{original}, map[string][]string{"actor": {"b"}}, true, true)
	cases := []struct {
		name, actor, board string
		id int
		body string
		want error
	}{
		{"empty actor", "", "b", 7, `{"name":"x"}`, ErrUnauthorized},
		{"empty board", "actor", "", 7, `{"name":"x"}`, ErrUnauthorized},
		{"no access", "other", "b", 7, `{"name":"x"}`, ErrUnauthorized},
		{"invalid id zero", "actor", "b", 0, `{"name":"x"}`, ErrInvalidID},
		{"invalid id negative", "actor", "b", -1, `{"name":"x"}`, ErrInvalidID},
		{"missing", "actor", "b", 8, `{"name":"x"}`, ErrNotFound},
		{"wrong board", "actor", "b", 9, `{"name":"x"}`, ErrNotFound},
		{"malformed", "actor", "b", 7, `{`, ErrBadBody},
		{"trailing", "actor", "b", 7, `{"name":"x"} {}`, ErrBadBody},
		{"null", "actor", "b", 7, `null`, ErrBadBody},
		{"empty object", "actor", "b", 7, `{}`, ErrBadBody},
		{"unknown", "actor", "b", 7, `{"name":"x","extra":1}`, ErrBadBody},
		{"empty name", "actor", "b", 7, `{"name":""}`, ErrBadBody},
		{"blank slug", "actor", "b", 7, `{"slug":"  \t"}`, ErrBadBody},
		{"blank title", "actor", "b", 7, `{"title":"\n"}`, ErrBadBody},
	}
	// Add a card on another board while retaining authorization for b.
	other := NewCardService([]Card{original, {ID: 9, Board: "other", Name: "x", Slug: "x", Title: "x"}}, map[string][]string{"actor": {"b"}}, true, true)
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			target := s
			if tc.name == "wrong board" { target = other }
			_, err := target.UpdateCard(tc.actor, tc.board, tc.id, []byte(tc.body))
			if err != tc.want { t.Fatalf("error = %v, want %v", err, tc.want) }
			if len(target.EventsCopy()) != 0 { t.Fatal("failed update emitted event") }
			if got := target.SearchCopy()[7]; got != original { t.Fatalf("failed update mutated card: %#v", got) }
		})
	}
}

func TestCardServiceDisabledAndNilSnapshots(t *testing.T) {
	s := NewCardService([]Card{{ID: 1, Board: "b", Name: "n", Slug: "s", Title: "t"}}, map[string][]string{"a": {"b"}}, false, false)
	if _, err := s.UpdateCard("a", "b", 1, []byte(`{"slug":"new"}`)); err != nil { t.Fatal(err) }
	if got := s.SearchCopy(); got == nil || len(got) != 0 { t.Fatalf("disabled search = %#v", got) }
	if got := s.EventsCopy(); got == nil || len(got) != 0 { t.Fatalf("disabled events = %#v", got) }
	var nilService *CardService
	if _, err := nilService.UpdateCard("a", "b", 1, []byte(`{"name":"x"}`)); err == nil { t.Error("nil update succeeded") }
	if got := nilService.SearchCopy(); got == nil || len(got) != 0 { t.Errorf("nil search = %#v", got) }
	if got := nilService.EventsCopy(); got == nil || len(got) != 0 { t.Errorf("nil events = %#v", got) }
}

